import * as React from "react";
import { useLocation } from "@reach/router";
import { Link } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import { FiMenu, FiX } from "react-icons/fi";
import navigationData from "../data/data.json";
import LanguageSelector from "./languageSelector";
import Logo from "./logo";

type MenuItemKey = "home" | "services" | "portfolio" | "about" | "contact";
type ServiceItem = {
  key: string;
  path: Record<string, string>;
};

const mobileMenuId = "primary-mobile-navigation";
const desktopServicesMenuId = "primary-services-navigation";
const mobileServicesMenuId = "primary-mobile-services-navigation";

function normalizePath(path: string) {
  return path.replace(/\/+$/, "") || "/";
}

export default function Navigation() {
  const { t } = useTranslation();
  const { language } = useI18next();
  const location = useLocation();
  const [isOpen, setIsOpen] = React.useState(false);
  const [isServicesOpen, setIsServicesOpen] = React.useState(false);
  const [isServicesMobileOpen, setIsServicesMobileOpen] = React.useState(false);
  const [activeId, setActiveId] = React.useState<MenuItemKey | null>(null);
  const servicesRef = React.useRef<HTMLDivElement | null>(null);
  const rafRef = React.useRef<number | null>(null);

  const menuItems = navigationData.menu as MenuItemKey[];
  const servicesMenu = (navigationData.servicesMenu || []) as ServiceItem[];
  const homeHref = `/${language}/`;
  const servicesHubHref = `/${language}/services/`;
  const portfolioHref = `/${language}/portfolio/`;
  const aboutHref = `/${language}/about/`;
  const contactHref = `/${language}/contact/`;
  const legacySelectedProjectsHref = `/${language}/selected-projects/`;

  const homePath = normalizePath(homeHref);
  const currentPath = normalizePath(location.pathname || homeHref);
  const mobileMenuLabel = (isOpen ? t("a11y.closeNavigation") : t("a11y.openNavigation")) as string;

  const hrefByItem: Record<MenuItemKey, string> = {
    home: homeHref,
    services: `${homeHref}#services`,
    portfolio: portfolioHref,
    about: aboutHref,
    contact: contactHref,
  };

  const sectionItems = menuItems.filter(
    (item) => item !== "home" && item !== "portfolio" && item !== "about" && item !== "contact"
  );

  const isHomeRoute = currentPath === homePath;
  const isServicesRoute =
    currentPath === normalizePath(servicesHubHref) ||
    currentPath.startsWith(`${normalizePath(servicesHubHref)}/`);

  const itemIsActive = (item: MenuItemKey) => {
    if (item === "home") {
      return isHomeRoute && activeId === "home";
    }

    if (item === "services") {
      return isServicesRoute || activeId === "services";
    }

    if (item === "portfolio") {
      return (
        currentPath === normalizePath(portfolioHref) ||
        currentPath === normalizePath(legacySelectedProjectsHref)
      );
    }

    if (item === "about") {
      return currentPath === normalizePath(aboutHref);
    }

    if (item === "contact") {
      return currentPath === normalizePath(contactHref);
    }

    return activeId === item;
  };

  const getServiceHref = (service: ServiceItem) => {
    const raw = service.path?.[language] || service.path?.en || "/";
    const cleaned = raw.replace(/^\/(en|fr)(?=\/)/, "");
    const withSlash = cleaned.startsWith("/") ? cleaned : `/${cleaned}`;
    return `/${language}${withSlash === "/" ? "" : withSlash}`;
  };

  const isServiceLinkActive = (href: string) => currentPath === normalizePath(href);

  const closeAllMenus = React.useCallback(() => {
    setIsOpen(false);
    setIsServicesOpen(false);
    setIsServicesMobileOpen(false);
  }, []);

  React.useEffect(() => {
    closeAllMenus();
  }, [closeAllMenus, language, location.pathname]);

  React.useEffect(() => {
    if (!isHomeRoute) {
      setActiveId(null);
      return undefined;
    }

    if (typeof window === "undefined") {
      return undefined;
    }

    const sections = sectionItems
      .map((item) => document.getElementById(item))
      .filter((section): section is HTMLElement => Boolean(section));

    const updateActive = () => {
      if (rafRef.current) {
        return;
      }

      rafRef.current = window.requestAnimationFrame(() => {
        rafRef.current = null;
        const offset = 140;
        const scrollPosition = window.scrollY + offset;
        let currentId: MenuItemKey = "home";

        sections.forEach((section) => {
          if (section.offsetTop <= scrollPosition) {
            currentId = section.id as MenuItemKey;
          }
        });

        setActiveId(currentId);
      });
    };

    updateActive();
    window.addEventListener("scroll", updateActive, { passive: true });
    window.addEventListener("resize", updateActive);

    return () => {
      window.removeEventListener("scroll", updateActive);
      window.removeEventListener("resize", updateActive);
      if (rafRef.current) {
        window.cancelAnimationFrame(rafRef.current);
      }
    };
  }, [isHomeRoute, sectionItems]);

  React.useEffect(() => {
    if (!isServicesOpen) {
      return undefined;
    }

    const handleClickOutside = (event: MouseEvent) => {
      if (servicesRef.current && !servicesRef.current.contains(event.target as Node)) {
        setIsServicesOpen(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsServicesOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [isServicesOpen]);

  const desktopLinkClass = (isActive: boolean) =>
    `relative inline-flex pb-1 text-neutral hover:text-accent ${
      isActive
        ? "font-semibold text-accent after:absolute after:-bottom-1 after:left-0 after:h-0.5 after:w-full after:bg-accent after:content-['']"
        : ""
    }`;

  const mobileLinkClass = (isActive: boolean) =>
    `flex justify-center rounded-md py-4 text-center text-neutral hover:text-accent ${
      isActive ? "font-semibold text-accent" : ""
    }`;

  return (
    <div className="w-full border-b border-neutral/20 bg-secondary/80 backdrop-blur">
      <div className="flex items-center justify-between gap-4 px-4 py-3 sm:px-8 lg:px-12">
        <Link to={homeHref} className="w-32" aria-label="Go to homepage">
          <Logo color="fill-secondary" />
        </Link>

        <nav className="hidden items-center gap-5 text-sm sm:flex">
          {menuItems.map((item) => {
            if (item === "services" && servicesMenu.length) {
              const isActive = itemIsActive(item);

              return (
                <div key={item} ref={servicesRef} className="relative">
                  <button
                    type="button"
                    className={desktopLinkClass(isActive)}
                    onClick={() => {
                      setActiveId("services");
                      setIsServicesOpen((previousState) => !previousState);
                    }}
                    aria-label={`${t("menu.services")} menu`}
                    aria-haspopup="true"
                    aria-expanded={isServicesOpen}
                    aria-controls={desktopServicesMenuId}
                  >
                    {t("menu.services")}
                    <span aria-hidden="true">▾</span>
                  </button>

                  <div
                    id={desktopServicesMenuId}
                    className={`absolute left-0 top-full mt-2 min-w-[16rem] rounded-xl border border-neutral/20 bg-secondary/95 p-2 shadow-lg backdrop-blur ${
                      isServicesOpen ? "block" : "hidden"
                    }`}
                  >
                    <Link
                      to={servicesHubHref}
                      className={`block rounded-lg px-3 py-2 text-sm hover:bg-primary/40 ${
                        currentPath === normalizePath(servicesHubHref)
                          ? "bg-primary/60 font-semibold text-accent"
                          : "font-semibold text-accent"
                      }`}
                      onClick={() => setIsServicesOpen(false)}
                    >
                      {t("menu.allServices")}
                    </Link>

                    {servicesMenu.map((service) => {
                      const href = getServiceHref(service);

                      return (
                        <Link
                          key={service.key}
                          to={href}
                          className={`block rounded-lg px-3 py-2 text-sm hover:bg-primary/40 hover:text-accent ${
                            isServiceLinkActive(href)
                              ? "bg-primary/60 font-semibold text-accent"
                              : "text-neutral"
                          }`}
                          onClick={() => setIsServicesOpen(false)}
                        >
                          {t(`services.${service.key}.h1`)}
                        </Link>
                      );
                    })}
                  </div>
                </div>
              );
            }

            const href = hrefByItem[item];
            const isActive = itemIsActive(item);

            if (item === "home" || item === "portfolio" || item === "about" || item === "contact") {
              return (
                <Link
                  key={item}
                  to={href}
                  className={desktopLinkClass(isActive)}
                  onClick={() => setActiveId(item)}
                >
                  {t(`menu.${item}`)}
                </Link>
              );
            }

            return (
              <a
                key={item}
                href={href}
                className={desktopLinkClass(isActive)}
                onClick={() => setActiveId(item)}
              >
                {t(`menu.${item}`)}
              </a>
            );
          })}
        </nav>

        <button
          type="button"
          onClick={() => setIsOpen((previousState) => !previousState)}
          className="rounded-md p-1 md:hidden"
          aria-label={mobileMenuLabel}
          aria-expanded={isOpen}
          aria-controls={mobileMenuId}
        >
          {isOpen ? <FiX size={24} /> : <FiMenu size={24} />}
        </button>

        <div className="text-xs text-neutral">
          <span className="sr-only">Language</span>
          <LanguageSelector data={navigationData} />
        </div>
      </div>

      {isOpen ? (
        <ul id={mobileMenuId} className="space-y-2 bg-primary p-4 shadow-md md:hidden">
          {menuItems.map((item) => {
            if (item === "services" && servicesMenu.length) {
              const isActive = itemIsActive(item);

              return (
                <li key={item} className="list-none space-y-2">
                  <button
                    type="button"
                    className={`${mobileLinkClass(isActive)} w-full`}
                    onClick={() => {
                      setActiveId("services");
                      setIsServicesMobileOpen((previousState) => !previousState);
                    }}
                    aria-label={`${t("menu.services")} menu`}
                    aria-haspopup="true"
                    aria-expanded={isServicesMobileOpen}
                    aria-controls={mobileServicesMenuId}
                  >
                    {t("menu.services")}
                  </button>

                  {isServicesMobileOpen ? (
                    <ul id={mobileServicesMenuId} className="flex flex-col gap-2 px-4">
                      <li className="list-none">
                        <Link
                          to={servicesHubHref}
                          className={`block rounded-lg px-3 py-2 text-center text-sm hover:text-accent ${
                            currentPath === normalizePath(servicesHubHref)
                              ? "bg-primary/60 font-semibold text-accent"
                              : "bg-secondary font-semibold text-accent"
                          }`}
                          onClick={closeAllMenus}
                        >
                          {t("menu.allServices")}
                        </Link>
                      </li>

                      {servicesMenu.map((service) => {
                        const href = getServiceHref(service);

                        return (
                          <li key={service.key} className="list-none">
                            <Link
                              to={href}
                              className={`block rounded-lg px-3 py-2 text-center text-sm hover:text-accent ${
                                isServiceLinkActive(href)
                                  ? "bg-primary/60 font-semibold text-accent"
                                  : "bg-secondary text-neutral"
                              }`}
                              onClick={closeAllMenus}
                            >
                              {t(`services.${service.key}.h1`)}
                            </Link>
                          </li>
                        );
                      })}
                    </ul>
                  ) : null}
                </li>
              );
            }

            const href = hrefByItem[item];
            const isActive = itemIsActive(item);

            if (item === "home" || item === "portfolio" || item === "about" || item === "contact") {
              return (
                <li key={item} className="list-none">
                  <Link
                    to={href}
                    className={mobileLinkClass(isActive)}
                    onClick={() => {
                      setActiveId(item);
                      setIsOpen(false);
                    }}
                  >
                    {t(`menu.${item}`)}
                  </Link>
                </li>
              );
            }

            return (
              <li key={item} className="list-none">
                <a
                  href={href}
                  className={mobileLinkClass(isActive)}
                  onClick={() => {
                    setActiveId(item);
                    setIsOpen(false);
                  }}
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            );
          })}
        </ul>
      ) : null}
    </div>
  );
}
